import{_ as o,C as s,o as l,c as f,E as a,a4 as d,b as r,w as e,a as g,a5 as x,j as n}from"./chunks/framework.2-Vke5-n.js";const C=JSON.parse('{"title":"可用性","description":"","frontmatter":{"sidebarDepth":4,"title":"可用性","author":"フューチャー株式会社","head":[["meta",{"name":"keywords","content":"非機能要件定義,可用性"}]]},"headers":[],"relativePath":"documents/forNFR/availability.md","filePath":"documents/forNFR/availability.md"}'),h={name:"documents/forNFR/availability.md"},c={class:"tip custom-block"};function E(A,t,p,b,B,u){const y=s("page-title"),i=s("Mermaid");return l(),f("div",null,[a(y),t[4]||(t[4]=d('<p>ずっと止まっても大丈夫なシステムは存在しない。可用性はどのようなシステムでも必ず問われる非機能要件の入口である。</p><h2 id="可用性とは" tabindex="-1">可用性とは <a class="header-anchor" href="#可用性とは" aria-label="Permalink to &quot;可用性とは&quot;">​</a></h2><p>可用性は単一の指標ではなく、複数の項目からなる。本章ではこれらを段階的に扱う。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">キーワード</th><th style="text-align:left;">内容</th><th style="text-align:left;">詳説</th></tr></thead><tbody><tr><td style="text-align:left;">継続性</td><td style="text-align:left;">運用スケジュール・目標復旧水準・稼働率</td><td style="text-align:left;">どの時間帯に・どれだけの割合で使え、障害からどこまで速く戻すか</td><td style="text-align:left;">本章の中核。基礎は本節、深掘りは<a href="#高可用性要件">高可用性要件</a></td></tr><tr><td style="text-align:left;">耐障害性</td><td style="text-align:left;">冗長化・単一障害点・フェイルオーバー</td><td style="text-align:left;">冗長化や単一障害点の排除で、そもそも止まりにくくする</td><td style="text-align:left;"><a href="#高可用性要件">高可用性要件</a></td></tr><tr><td style="text-align:left;">災害対策</td><td style="text-align:left;">DR・BCP</td><td style="text-align:left;">大規模災害時の復旧と事業継続</td><td style="text-align:left;"><a href="#高可用性要件">高可用性要件</a></td></tr></tbody></table><p>なお、これらを厳密に定義するときの詳細な項目と値の例は、<a href="./appendix.html#可用性の定義項目チェックリスト">Appendix「可用性の定義項目チェックリスト」</a>にまとめている。網羅的に詰める必要があるのは主にミッションクリティカルなシステムで、多くのシステムは基本項目だけで足りる。</p><p>可用性目標の中核は継続性である。これは次の3つで定める（IPA 非機能要求グレードの中項目「継続性」に対応する）。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">運用スケジュール</td><td style="text-align:left;">そもそも稼働している必要がある時間帯（平日 9–17 時、24 時間 365 日など）</td></tr><tr><td style="text-align:left;">目標復旧水準</td><td style="text-align:left;">障害時にどれだけの時間で復旧するか（RTO＝目標復旧時間）、どの時点までデータを戻すか（RPO＝目標復旧時点）</td></tr><tr><td style="text-align:left;">稼働率</td><td style="text-align:left;">その運用スケジュールの中で、どれだけの割合でサービスを提供できるか</td></tr></tbody></table><p>3つのうち出発点になるのが運用スケジュールである。とくに「24 時間 365 日止められないのか、それとも定期的にメンテナンスウィンドウ（計画停止の枠）を取れるのか」は、後段を大きく左右する。夜間や週末に止めてよいなら、その枠でメンテナンス・バッチ・切り替えを行え、設計やコストも楽になる。逆に 24/365 が求められると、無停止でのアップデートや冗長切り替えが前提になり、難度と費用が跳ね上がる。</p><p>運用スケジュールは、稼働率の分母（稼働を求める時間）を定める。計画停止をどう扱うか（稼働率の計算では停止時間に含めない）の前提にもなる。</p><p>これらを独立に扱わないのは、互いに依存するためである。運用スケジュールが決まらなければ稼働率の分母が定まらず、目標復旧水準が決まらなければ、停止時間の内訳（障害そのものの時間＋復旧処理の時間）も定まらない。</p><p>ただし、稼働率と目標復旧水準（RTO）は、受け持つ役割が違う。稼働率は一定期間の停止時間を合計した割合であり、「一度の障害でどれだけ長く止まるか」までは縛らない。例えば「稼働率 99.9％（年間約 8.7 時間まで停止可）」という同じ要件でも、次のどちらの止まり方でも満たせてしまう。</p><table tabindex="0"><thead><tr><th style="text-align:left;">停止パターン</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">細切れで止まる</td><td style="text-align:left;">深夜に1分ずつ、年間を通して合計 8.7 時間分が分散して発生する</td></tr><tr><td style="text-align:left;">一度にまとめて止まる</td><td style="text-align:left;">年間で最も重要な繁忙日に、8.7 時間をまるごと使い切る</td></tr></tbody></table><p>どちらも稼働率は同じだが、事業が受ける痛みはまったく違う。そこで、一度の停止で業務が耐えられる長さは、稼働率とは別に RTO（目標復旧時間）で定める。両者は次のように補完し合う。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">稼働率</td><td style="text-align:left;">一定期間の停止の「累計」に上限をかける</td></tr><tr><td style="text-align:left;">RTO</td><td style="text-align:left;">一度の停止の「長さ」に上限をかける</td></tr></tbody></table><p>稼働率は、期待（運用スケジュール）に対する提供割合である。注意したいのは、停止時間の数え方である。停止時間には、障害そのものの継続時間だけでなく、その後の復旧処理の時間も含む。</p><div class="tip custom-block"><p class="custom-block-title">稼働率の相場観</p><p>24 時間 365 日運用での、稼働率と年間停止時間の目安を示す。</p><table tabindex="0"><thead><tr><th style="text-align:left;">稼働率</th><th style="text-align:left;">年間の停止許容時間（目安）</th></tr></thead><tbody><tr><td style="text-align:left;">99％（ツーナイン）</td><td style="text-align:left;">約 3.6 日</td></tr><tr><td style="text-align:left;">99.9％（スリーナイン）</td><td style="text-align:left;">約 8.7 時間</td></tr><tr><td style="text-align:left;">99.99％（フォーナイン）</td><td style="text-align:left;">約 52 分</td></tr><tr><td style="text-align:left;">99.999％（ファイブナイン）</td><td style="text-align:left;">約 5 分</td></tr><tr><td style="text-align:left;">99.9999％（シックスナイン）</td><td style="text-align:left;">約 32 秒</td></tr></tbody></table><p>「9」が1つ増えるごとに停止許容は約 1/10 になり、必要なコストと構成の難度は跳ね上がる。まずはこの相場観を持っておきたい（どの水準を選ぶかは <a href="#一般レベルの可用性要件">一般レベルの可用性要件</a>・<a href="#高可用性要件">高可用性要件</a> で扱う）。</p><p>一般的な業務システムは 99.5〜99.9％ に収まることが多く、高可用性要件に進まないケースはこのあたりに着地する。99.99％ 以上は、金融・通信など可用性が重要ドライバとなる領域の水準である。</p></div><div class="tip custom-block"><p class="custom-block-title">稼働率を分かりやすく表現する例</p><p>稼働率を「月あたり30分停止が何回か」で表現すると、相手によっては伝わりやすい。●1つが、30分の停止1回を示す。</p><table tabindex="0"><thead><tr><th style="text-align:center;">1月</th><th style="text-align:center;">2月</th><th style="text-align:center;">3月</th><th style="text-align:center;">4月</th><th style="text-align:center;">5月</th><th style="text-align:center;">6月</th><th style="text-align:center;">7月</th><th style="text-align:center;">8月</th><th style="text-align:center;">9月</th><th style="text-align:center;">10月</th><th style="text-align:center;">11月</th><th style="text-align:center;">12月</th><th style="text-align:left;">総合停止時間</th><th style="text-align:left;">稼働率</th></tr></thead><tbody><tr><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:left;">30分</td><td style="text-align:left;">99.994％</td></tr><tr><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:left;">1時間</td><td style="text-align:left;">99.989％</td></tr><tr><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:left;">1.5時間</td><td style="text-align:left;">99.983％</td></tr><tr><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:left;">2時間</td><td style="text-align:left;">99.977％</td></tr><tr><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:left;">3時間</td><td style="text-align:left;">99.966％</td></tr><tr><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:left;">6時間</td><td style="text-align:left;">99.932％</td></tr><tr><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:left;">9時間</td><td style="text-align:left;">99.897％</td></tr><tr><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:left;">12時間</td><td style="text-align:left;">99.863％</td></tr><tr><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:center;">●●</td><td style="text-align:left;">16時間</td><td style="text-align:left;">99.817％</td></tr></tbody></table><p>仮に、年1回30分であれば、フォーナイン（99.99％）を維持できるが、年2回になると維持できない。</p></div><div class="tip custom-block"><p class="custom-block-title">稼働率の定義と計算</p><p>稼働率は、稼働を求める時間のうち、実際に稼働できた時間の割合で表す。値が高いほど、期待に近い。</p><p>稼働率（％）＝ <em>実際に稼働できた時間</em> / <em>稼働を求める時間</em> × 100</p><p>例えば 10 時間（600 分）の稼働を求める場合に、障害が 10 分続き、その復旧処理に 60 分かかったとすると、停止時間は合計 70 分。稼働率は (600 − 70) ÷ 600 × 100 ＝ 88.3％ となる。</p><p>なお、<strong>計画メンテナンスによる停止は、この停止時間に含めない</strong>。事前に告知し、運用スケジュールの外として扱うためである。含めてしまうと、計画停止のたびに稼働率が下がり、実態を表せなくなる。また、停止時間のうち見落とされやすいのは「復旧処理の時間」である。原因調査・切り戻し・データ復旧・業務再開の確認に時間がかかり、障害そのものより長くなる。停止時間を見積もるときは、この復旧処理を軽く見ない。</p></div><div class="tip custom-block"><p class="custom-block-title">信頼性（MTBF など）はどこで扱うか</p><p>MTBF（平均故障間隔）や故障率といった伝統的な信頼性の指標は、本章では独立して扱わず、継続性（稼働率・RTO／RPO）に含めている。利用者が最終的に気にするのは、部品がどれくらいの頻度で壊れるかではなく、結果としてどれだけ止まらなかったか（稼働率）、壊れてもどれだけ早く戻せるか（RTO・RPO）だからである。稼働率は、故障間隔（MTBF）と平均修復時間（MTTR）を合わせた結果指標であり、そちらで充足する。</p><p>とくにクラウドでは、ハードウェアの信頼性は事業者が管理し、利用側には SLA や稼働率としてしか見えない。発注者自身が部品交換のためにサーバールームで作業する必要が無い以上、コンポーネントレベルの信頼性を定義したい場面は減っている。</p></div><div class="tip custom-block"><p class="custom-block-title">可用性と耐久性の混同に注意する</p><p>可用性と耐久性は、似ているようで別物である。混同すると「冗長化したのだからデータも安全だ」といった誤解につながる。</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">問い</th><th style="text-align:left;">効く対策</th><th style="text-align:left;">関連する指標</th></tr></thead><tbody><tr><td style="text-align:left;">可用性</td><td style="text-align:left;">サービスを使い続けられるか</td><td style="text-align:left;">冗長化・フェイルオーバー</td><td style="text-align:left;">稼働率・RTO</td></tr><tr><td style="text-align:left;">耐久性</td><td style="text-align:left;">預けたデータが失われないか</td><td style="text-align:left;">バックアップ・レプリケーション・複数拠点保管</td><td style="text-align:left;">RPO</td></tr></tbody></table><p>クラウドストレージは、この2つを別々の数字で公開している。例えば同じサービスでも、可用性は 99.9％ 台なのに対し、耐久性は 99.999999999％（イレブンナイン）といった桁違いの水準が示される。高い可用性はデータの保全を保証せず、高い耐久性は常時アクセスできることを保証しない。両者は別の要件として、別の手立てで確保する。</p></div><h2 id="可用性要件の進め方" tabindex="-1">可用性要件の進め方 <a class="header-anchor" href="#可用性要件の進め方" aria-label="Permalink to &quot;可用性要件の進め方&quot;">​</a></h2><p>可用性をどこまで作り込むかは、時間・費用・業務要求のバランスで決める。すべてのシステムで精緻な設計が要るわけではない。判断は2段階で行う。まずベースラインで要求レベルを置く。それで業務要求を満たせるなら一般レベルで確定し、満たせないなら高可用性要件へ進む。</p>',22)),(l(),r(x,null,{default:e(()=>[a(i,{id:"mermaid-798",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20theme%3A%20neutral%0A%20%20look%3A%20handDrawn%0A---%0Aflowchart%20LR%0A%20%20%20%20A((%E9%96%8B%E5%A7%8B))%20--%3E%20B%5B%22%E3%83%99%E3%83%BC%E3%82%B9%E3%83%A9%E3%82%A4%E3%83%B3%E3%81%A7%3Cbr%2F%3E%E8%A6%81%E6%B1%82%E3%83%AC%E3%83%99%E3%83%AB%E3%82%92%E7%BD%AE%E3%81%8F%22%5D%0A%20%20%20%20B%20--%3E%20C%7B%22%E4%B8%80%E8%88%AC%E3%83%AC%E3%83%99%E3%83%AB%E3%81%A7%3Cbr%2F%3E%E6%A5%AD%E5%8B%99%E8%A6%81%E6%B1%82%E3%82%92%E6%BA%80%E3%81%9F%E3%81%9B%E3%82%8B%E3%81%8B%EF%BC%9F%22%7D%0A%20%20%20%20C%20--%20%E6%BA%80%E3%81%9F%E3%81%9B%E3%82%8B%20--%3E%20D%5B%22%E4%B8%80%E8%88%AC%E3%83%AC%E3%83%99%E3%83%AB%E3%81%A7%E7%A2%BA%E5%AE%9A%22%5D%0A%20%20%20%20C%20--%20%E6%BA%80%E3%81%9F%E3%81%9B%E3%81%AA%E3%81%84%20--%3E%20E%5B%22%E9%AB%98%E5%8F%AF%E7%94%A8%E6%80%A7%E8%A6%81%E4%BB%B6%E3%81%B8%3Cbr%2F%3E%EF%BC%88%E7%A8%BC%E5%83%8D%E7%8E%87%E3%83%BB%E7%81%BD%E5%AE%B3%E5%AF%BE%E7%AD%96%3Cbr%2F%3E%E3%81%8B%E3%82%89%E6%B7%B1%E6%8E%98%E3%82%8A%E8%A6%B3%E7%82%B9%E3%82%92%E9%81%B8%E3%81%B6%EF%BC%89%22%5D%0A%20%20%20%20D%20--%3E%20F((%E8%A6%81%E4%BB%B6%E7%A2%BA%E5%AE%9A))%0A%20%20%20%20E%20--%3E%20F%0A%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=d('<h2 id="一般レベルの可用性要件" tabindex="-1">一般レベルの可用性要件 <a class="header-anchor" href="#一般レベルの可用性要件" aria-label="Permalink to &quot;一般レベルの可用性要件 {#一般レベルの可用性要件}&quot;">​</a></h2><p>多くのシステムにとって、可用性は特別に作り込む対象ではなく、標準的な作り方で十分に満たせる。ここでは、そうしたケースでの決め方を示す。ここで足りると判断できれば、次の<a href="#高可用性要件">高可用性要件</a>には進まず、要件を確定してよい。</p><p>一般レベルでは、次の3ステップで要件を確定する。</p><ol><li><strong>要求レベルを置く</strong><br> ベースライン（IPA 非機能要求グレードなら社会的影響度の3モデル：極大／大／限定的）から選ぶ（→ 第一部 <a href="./overview.html#step6">STEP6 ベースラインの設定</a>）。停止しても影響が社内にとどまる、あるいは軽微な業務（社内の情報共有ツールなど）なら、影響度は「限定的」である。この場合、稼働率でいえば 99.5〜99.9％ が1つの目安になる（相場観の詳細は<a href="#可用性とは">可用性とは</a>を参照）。</li><li><strong>標準構成で満たす</strong><br> 冗長化（クラウドならマルチ AZ、オンプレなら機器の二重化）、単一障害点の排除、バックアップとリストアの整備。クラウドのマネージドサービスを素直に組めば、多くはこの水準に収まる。&quot;特別に作り込む&quot;のではなく、&quot;標準から外さない&quot;レベルである。</li><li><strong>実績で妥当性を確かめる</strong><br> 数値ありきで決めず、実績と突き合わせる。現行システムがあれば稼働実績と障害履歴を振り返り、「実際どれくらい止まり、業務はどれだけ困ったか」を確認する（→ 第一部 <a href="./overview.html#step2">STEP2 ビジネスコンテキストの理解</a>・<a href="./overview.html#who">Who章：現行システムの運用者</a>）。新規なら類似システムの水準を拠り所にする。</li></ol><p>顧客との合意も、このレベルでは重くない。「業務への影響は限定的なので、標準構成で稼働率○％程度を目標にします」と確認する程度でこと足りる。停止の痛みを丁寧に引き出したり、コストと水準の綱引きをしたりといった重い合意形成は、可用性が重要ドライバとなるケース（次章）で行う。</p><p>一方、次のいずれかに当てはまるなら、一般レベルで止めず<a href="#高可用性要件">高可用性要件</a>へ進む。ただし、費用・合意形成・設計構築の負担は相応に増える。</p><table tabindex="0"><thead><tr><th style="text-align:left;">判断基準</th><th style="text-align:left;">例</th></tr></thead><tbody><tr><td style="text-align:left;">ミッションクリティカル性が高い</td><td style="text-align:left;">決済、認証基盤、社会インフラ、祖業・基幹業務システム</td></tr><tr><td style="text-align:left;">事業側と構築側の期待値に大きなギャップがある</td><td style="text-align:left;">「24時間365日絶対に止めるな」が技術的・予算的に非現実的な水準</td></tr><tr><td style="text-align:left;">過去に重大な障害・訴訟・信用失墜の実績がある</td><td style="text-align:left;">同種システムで重大インシデントを起こした経験がある</td></tr><tr><td style="text-align:left;">妥当なベースラインが存在しない</td><td style="text-align:left;">前例のない新規事業、類似システムが社内外に無い</td></tr><tr><td style="text-align:left;">規制・コンプライアンス要求がある</td><td style="text-align:left;">重要インフラ15分野、金融、医療などの法令・ガイダンス上の要求</td></tr><tr><td style="text-align:left;">契約上の罰則・損害賠償リスクがある</td><td style="text-align:left;">SLA 未達時に違約金や契約解除条項が存在する</td></tr></tbody></table><p>迷う場合は、まず&quot;止まったときの痛み&quot;の大小をざっくり掴んで見極めるとよい。</p><h2 id="バックアップとデータ保全" tabindex="-1">バックアップとデータ保全 <a class="header-anchor" href="#バックアップとデータ保全" aria-label="Permalink to &quot;バックアップとデータ保全 {#バックアップとデータ保全}&quot;">​</a></h2><p>どのシステムでも、データが失われないための備えは必要である。可用性（使い続けられるか）とは別に、耐久性（データが失われないか）を支える土台であり、ミッションクリティカルかどうかに関わらず必ず詰める（→「可用性と耐久性の混同に注意する」）。</p><p>可用性の要件として決めるのは、次の水準・範囲である。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">許容するデータ損失（RPO）</td><td style="text-align:left;">障害時にどの時点まで戻せればよいか（継続性の要素。→<a href="#可用性とは">可用性とは</a>）</td></tr><tr><td style="text-align:left;">データ保全の範囲</td><td style="text-align:left;">リージョンや拠点の全損のような大規模障害に備え、別リージョンや別拠点へバックアップするかどうか</td></tr></tbody></table><p>一方、バックアップの取得頻度・世代管理・ジョブ監視・リストア訓練といった運用は運用保守性で、取得方式や保管先といった構成は設計で扱う。バックアップからのリストアでは間に合わないほど短い RTO や、無停止での切り替え（スタンバイサイト、マルチリージョン稼働）が要る場合は、<a href="#高可用性要件">高可用性要件</a>の<a href="#災害対策と事業継続">災害対策（DR・BCP）</a>で扱う。</p><h2 id="高可用性要件" tabindex="-1">高可用性要件 <a class="header-anchor" href="#高可用性要件" aria-label="Permalink to &quot;高可用性要件&quot;">​</a></h2><p>可用性が重要ドライバだと判明したら、一般レベルを超えて精緻に設計する。ここからは稼働率を軸に、事業の期待を実現可能な要件へ落とし込む道筋を扱う。</p><h3 id="稼働率の4つの視点" tabindex="-1">稼働率の4つの視点 <a class="header-anchor" href="#稼働率の4つの視点" aria-label="Permalink to &quot;稼働率の4つの視点&quot;">​</a></h3><p>「稼働率」という一語は、立場によって指すものが違う。同じ数字を議論しているつもりで、実は別の意味の稼働率を話してしまうと噛み合わない。いま4つのどれを論じているかを、関係者間で明確にする。</p><table tabindex="0"><thead><tr><th style="text-align:left;">種別</th><th style="text-align:left;">位置づけ</th><th style="text-align:left;">意味</th><th style="text-align:left;">主な関心者</th></tr></thead><tbody><tr><td style="text-align:left;">要求値</td><td style="text-align:left;">事業上の期待</td><td style="text-align:left;">事業文脈から導かれる、止まりにくさへの期待</td><td style="text-align:left;">事業責任者・業務主管部署</td></tr><tr><td style="text-align:left;">要件</td><td style="text-align:left;">合意事項</td><td style="text-align:left;">目標値の合理性と未達時の改善責任を合意したもの</td><td style="text-align:left;">プロジェクト責任者</td></tr><tr><td style="text-align:left;">設計値</td><td style="text-align:left;">理論上限</td><td style="text-align:left;">要件を実現する構成が理論上出せる上限値</td><td style="text-align:left;">アーキテクト</td></tr><tr><td style="text-align:left;">実績値</td><td style="text-align:left;">結果</td><td style="text-align:left;">運用で得られた実際の記録値</td><td style="text-align:left;">運用部門</td></tr></tbody></table><p>この4つは単なる分類ではなく、事業の期待（要求値）を約束（要件）にし、設計（設計値）で裏づけ、運用（実績値）で検証していく一連の流れでもある。以下、視点ごとに勘所を示す。</p><h4 id="要求値-事業の期待を引き出す" tabindex="-1">要求値（事業の期待を引き出す） <a class="header-anchor" href="#要求値-事業の期待を引き出す" aria-label="Permalink to &quot;要求値（事業の期待を引き出す）&quot;">​</a></h4><p>要求値は事業の期待そのものであり、システムの内側ではなく事業の状況で決まる。これを踏まえずに数字を設定すると、以降の要件・設計値の議論が「根拠のない数字合わせ」になりやすい。要求水準は、主に「事業の局面」と「停止の影響度」によって変わる。</p><h5 id="事業の局面" tabindex="-1">事業の局面 <a class="header-anchor" href="#事業の局面" aria-label="Permalink to &quot;事業の局面&quot;">​</a></h5><p>可用性に投下できる予算は、局面によって次のように変わる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">局面</th><th style="text-align:left;">特徴</th></tr></thead><tbody><tr><td style="text-align:left;">拡大期</td><td style="text-align:left;">可用性への投資を積極化する圧力が働く。「多少コストがかかっても止めるな」</td></tr><tr><td style="text-align:left;">縮小期</td><td style="text-align:left;">コスト削減圧力で目標が下がりうる。「最低限で構わない」</td></tr><tr><td style="text-align:left;">探索期</td><td style="text-align:left;">変化への対応力を優先し、最小限からはじめる。「まずは最小限で、事業の成り行きを見て」</td></tr></tbody></table><p>加えて、システム自体のライフサイクルも効く。新規構築時は投資を得やすい一方、運用・保守や刷新前の時期になるほど予算は厳しくなり、可用性を上げる交渉は通りにくくなる。</p><h5 id="停止の影響度" tabindex="-1">停止の影響度 <a class="header-anchor" href="#停止の影響度" aria-label="Permalink to &quot;停止の影響度&quot;">​</a></h5><p>停止が競合への顧客流出に直結したり、売上への影響が大きかったりするほど、高い稼働率が求められる。逆に、利用頻度の低い社内システムなどでは、コストとのバランスで水準を下げる判断も合理的である。</p><p>要求水準を引き出すときは、技術用語でなく「停止したときの痛み」で語ると、事業側と認識を合わせやすい。稼働率のような1つの数値だけでは、いつ・どのくらいの長さで止まるかまでは表せない（→<a href="#可用性とは">可用性とは</a>）。だから、次のように「どんな止まり方が、どれだけ痛いか」を具体化しておく。</p><table tabindex="0"><thead><tr><th style="text-align:left;">痛みの種類</th><th style="text-align:left;">具体的な状況</th><th style="text-align:left;">表現することば</th></tr></thead><tbody><tr><td style="text-align:left;">頻度の痛み</td><td style="text-align:left;">頻繁に停止する</td><td style="text-align:left;">「しょっちゅう止まる」</td></tr><tr><td style="text-align:left;">長さの痛み</td><td style="text-align:left;">停止時間が長い</td><td style="text-align:left;">「止まったら長い」</td></tr><tr><td style="text-align:left;">タイミングの痛み</td><td style="text-align:left;">繁忙期・月末に止まる</td><td style="text-align:left;">「よりによって月末に止まる」</td></tr><tr><td style="text-align:left;">検知の痛み</td><td style="text-align:left;">止まったことに気づかない</td><td style="text-align:left;">「気づいたら止まっていた」</td></tr><tr><td style="text-align:left;">回復の痛み（戻らない）</td><td style="text-align:left;">復旧に時間がかかる</td><td style="text-align:left;">「直ったと思ったらまだ使えない」</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">可用性への投資を、期待損失から見積もる</p><p>可用性の要件は顧客が決めるものだが、コンサルタントとしては「どこまで投資すべきか」を経済的に見積もる視点を持っておきたい。</p><p>出発点は、停止による期待損失である。おおよそ「1回あたりの損失額 × 発生頻度」で見積もれる。損失には停止中の直接的な売上減だけでなく、レピュテーション低下による顧客離反や見込み顧客の取り逃がしも、ある程度は織り込める。</p><p>この期待損失が、可用性に投じてよい金額の目安になる。備えのコストが、それによって避けられる期待損失を下回るなら、ホットスタンバイやウォームスタンバイ、あるいは高い稼働率への投資は正当化できる。逆に、期待損失に見合わない過剰な投資は避ける（→ 心得「過剰品質を避ける」）。</p><p>この費用対効果の試算を顧客との議論で前面に出すかは状況によるが、常に念頭に置くことが、コンサルタントの役割である。</p></div><h4 id="要件-実現できる約束として合意する" tabindex="-1">要件（実現できる約束として合意する） <a class="header-anchor" href="#要件-実現できる約束として合意する" aria-label="Permalink to &quot;要件（実現できる約束として合意する）&quot;">​</a></h4><p>要求値を、検証可能で実現可能な「要件」に変換して合意する。合意にあたっては、目標値が次の3点を満たすことを確認する（→ 第一部 <a href="./overview.html#step10">STEP10 ステークホルダー合意</a>）。</p><ul><li>業務要求に照らして合理的であること（なぜその水準なのかを、事業の根拠で説明できる）</li><li>達成できる設計が合理的に描けること（アーキテクチャとして実現可能である）</li><li>未達のときに、原因を説明し改善できること</li></ul><p>要求値を要件に落とすときは、あわせて次の2点に留意する。</p><ul><li><strong>定性的な期待は必ず数値にすること</strong><br> 「止まりにくいこと」のままではテストで合否を判定できず、認識のズレを生む（例: 稼働率 99.9％ 以上、年間停止時間 8.7 時間以内）。</li><li><strong>機能ごとに水準を分けるか検討すること</strong><br> 1つのシステムでも、決済機能と管理画面では停止したときの影響が違うため、同じ数値を当てはめない。</li></ul><p>なお、要件は単独では確定できない。事業の期待（要求値）を、アーキテクチャの理論上限（設計値）と照らし合わせ、実現できる水準として確定する。</p><div class="tip custom-block"><p class="custom-block-title">アンチパターン：可用性を「機能」として書いてしまう</p><p>可用性は「どれくらい安定して・長く使えるか」という水準の話であって、作り込む機能そのものではない。慣れないうちは、可用性への期待を機能要件として書いてしまうことがある。</p><table tabindex="0"><thead><tr><th style="text-align:left;">書き方</th><th style="text-align:left;">例</th></tr></thead><tbody><tr><td style="text-align:left;">❌️ 機能として書く</td><td style="text-align:left;">「障害時に自動で切り替わる機能を追加する」 「ログイン画面が常に表示されるようにする」</td></tr><tr><td style="text-align:left;">✅️ 水準として書く</td><td style="text-align:left;">「稼働率 99.9％ 以上」 「フェイルオーバーの切り替わりは5分以内」</td></tr></tbody></table><p>機能として書くと、テストや SLA で「どこまで満たせば合格か」を定量的に判定できず、後工程で混乱する。自動切り替えのような仕組みは、あくまで水準を実現する手段であって、要件そのものではない（→ <a href="./overview.html#what">第一部 What</a>）。</p></div><div class="tip custom-block"><p class="custom-block-title">アンチパターン：技術的な実現手段まで要件に書いてしまう</p><p>可用性の要件は、何を・どの水準で達成したいかに留める。どう実現するかといった具体的な構成は、設計フェーズの領分である。技術に明るい人ほど、要件定義の段階で作り方まで決めてしまいやすい。</p><table tabindex="0"><thead><tr><th style="text-align:left;">書き方</th><th style="text-align:left;">例</th></tr></thead><tbody><tr><td style="text-align:left;">❌️ 実現手段まで書く</td><td style="text-align:left;">「Kubernetes の Replica 数を3にする」 「DB は同期レプリケーションでフェイルオーバーさせる」</td></tr><tr><td style="text-align:left;">✅️ 水準で書く</td><td style="text-align:left;">「RTO 5分以内・RPO 1分以内」</td></tr></tbody></table><p>構成を要件で決め打ちすると、設計者の自由度を奪い、より良い実現手段が出にくくなる。手段が悪いのではなく、決める場所が違う。要件は水準まで、どう実現するかは設計へ委ねる（→ <a href="./overview.html#step11">第一部 STEP11 アーキテクチャ設計への反映</a>）。</p></div><h4 id="設計値-アーキテクチャの理論上限を見積もる" tabindex="-1">設計値（アーキテクチャの理論上限を見積もる） <a class="header-anchor" href="#設計値-アーキテクチャの理論上限を見積もる" aria-label="Permalink to &quot;設計値（アーキテクチャの理論上限を見積もる）&quot;">​</a></h4><p>設計値は、採用する構成が理論上どこまでの稼働率を出せるかの上限である。これは &quot;設計&quot; の話でもあるので、要件定義の趣旨からは外れる。ただし、知識としては押さえておくべきである。</p><p>見積もるときは、次の3点に注意する。</p><ul><li><strong>最弱リンクに気をつける</strong><br> 全体の稼働率は、最も弱い要素に引っ張られる。直列構成では各要素の稼働率の掛け算になり、最も低い要素で頭打ちになる。冗長化（並列化）で引き上げられるが、並列化できない単一依存点があると、そこが上限を決める。オンプレではストレージがその単一依存点になりやすい。</li><li><strong>現実的な水準に落とし込む</strong><br> 99.999％（ファイブナイン）のような値は金融・通信など特定領域の水準で、一般の業務システムとはかけ離れる（相場観は<a href="#可用性とは">可用性とは</a>を参照）。高い数字に引きずられて要件を置くと、当初のコスト感では実現できない構成を追うことになる。</li><li><strong>SLA の限界を知っておく</strong><br> クラウドの SLA が示す停止時間は「サービスが応答するか」の話であって、「業務が正常に再開できるか」とは別物である。障害が収まった後の復旧処理の時間は SLA に含まれないため、設計段階で復旧のシナリオまで見通し、RTO に織り込んでおく。</li></ul>',42)),n("div",c,[t[2]||(t[2]=n("p",{class:"custom-block-title"},"直列・並列構成と最弱リンク",-1)),t[3]||(t[3]=n("p",null,"稼働率は要素の掛け算で決まる。冗長化（並列化）は大きく効くが、並列化できない単一依存点があると、そこで頭打ちになる。",-1)),(l(),r(x,null,{default:e(()=>[a(i,{id:"mermaid-1324",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20theme%3A%20neutral%0A%20%20look%3A%20handDrawn%0A---%0Aflowchart%20TD%0A%20%20%20%20classDef%20greenNode%20fill%3A%23e6f4ea%2Cstroke%3A%231e8e3e%2Cstroke-width%3A1.5px%2Ccolor%3A%23333%3B%0A%20%20%20%20classDef%20orangeNode%20fill%3A%23fef7e0%2Cstroke%3A%23d99900%2Cstroke-width%3A1.5px%2Ccolor%3A%23333%3B%0A%20%20%20%20classDef%20redNode%20fill%3A%23fce8e6%2Cstroke%3A%23d93025%2Cstroke-width%3A1.5px%2Ccolor%3A%23333%3B%0A%20%20%20%20classDef%20textOnly%20fill%3Anone%2Cstroke%3Anone%2Ccolor%3A%23333%3B%0A%20%20%20%20classDef%20invisible%20fill%3Anone%2Cstroke%3Anone%3B%0A%0A%20%20%20%20subgraph%20SERIAL%20%5B%22%E7%9B%B4%E5%88%97%E6%A7%8B%E6%88%90%22%5D%0A%20%20%20%20%20%20direction%20TD%0A%20%20%20%20%20%20S_A%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20A%3Cbr%2F%3E99.9%25%22%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20S_B%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20B%3Cbr%2F%3E99.9%25%22%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20S_C%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20C%3Cbr%2F%3E99.5%25%EF%BC%88%E6%9C%80%E5%BC%B1%EF%BC%89%22%5D%3A%3A%3AorangeNode%0A%20%20%20%20%20%20S_Total%3E%E5%85%A8%E4%BD%93%E7%A8%BC%E5%83%8D%E7%8E%87%3Cbr%2F%3E%E2%89%92%2099.3%25%5D%3A%3A%3AorangeNode%0A%20%20%20%20%20%20S_Text%5B%22%E6%8E%9B%E3%81%91%E7%AE%97%E3%81%A7%E4%B8%8B%E3%81%8C%E3%82%8B%22%5D%3A%3A%3AtextOnly%0A%20%20%20%20%20%20S_A%20--%3E%20S_B%0A%20%20%20%20%20%20S_B%20--%3E%20S_C%0A%20%20%20%20%20%20S_C%20--%3E%20S_Total%0A%20%20%20%20%20%20S_Total%20---%20S_Text%0A%20%20%20%20end%0A%20%20%20%20subgraph%20PARALLEL%20%5B%22%E4%B8%A6%E5%88%97%E6%A7%8B%E6%88%90%EF%BC%88%E5%86%97%E9%95%B7%E5%8C%96%EF%BC%89%22%5D%0A%20%20%20%20%20%20direction%20TD%0A%20%20%20%20%20%20P_Split(%22%20%22)%3A%3A%3Ainvisible%0A%20%20%20%20%20%20P_A1%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20A1%3Cbr%2F%3E99.9%25%22%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20P_A2%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20A2%3Cbr%2F%3E99.9%25%22%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20P_Total%3E%E5%85%A8%E4%BD%93%E7%A8%BC%E5%83%8D%E7%8E%87%3Cbr%2F%3E%E2%89%92%2099.9999%25%3Cbr%2F%3E%E5%A4%A7%E5%B9%85%E3%81%AB%E5%90%91%E4%B8%8A%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20P_Text%5B%22%E5%86%97%E9%95%B7%E5%8C%96%E3%81%A7%E6%94%B9%E5%96%84%E3%81%A7%E3%81%8D%E3%82%8B%22%5D%3A%3A%3AtextOnly%0A%20%20%20%20%20%20P_Split%20--%3E%20P_A1%0A%20%20%20%20%20%20P_Split%20--%3E%20P_A2%0A%20%20%20%20%20%20P_A1%20--%3E%20P_Total%0A%20%20%20%20%20%20P_A2%20--%3E%20P_Total%0A%20%20%20%20%20%20P_Total%20---%20P_Text%0A%20%20%20%20end%0A%20%20%20%20subgraph%20DEP%20%5B%22%E5%8D%98%E4%B8%80%E4%BE%9D%E5%AD%98%E7%82%B9%22%5D%0A%20%20%20%20%20%20direction%20TD%0A%20%20%20%20%20%20D_Split(%22%20%22)%3A%3A%3Ainvisible%0A%20%20%20%20%20%20D_B1%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20B1%3Cbr%2F%3E99.9%25%22%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20D_B2%5B%22%E3%82%B5%E3%83%BC%E3%83%90%20B2%3Cbr%2F%3E99.9%25%22%5D%3A%3A%3AgreenNode%0A%20%20%20%20%20%20D_Storage%5B(%22%E3%82%B9%E3%83%88%E3%83%AC%E3%83%BC%E3%82%B8%3Cbr%2F%3E99.5%25%EF%BC%88%E5%8D%98%E4%B8%80%EF%BC%89%22)%5D%3A%3A%3AredNode%0A%20%20%20%20%20%20D_Total%3E%E5%85%A8%E4%BD%93%E7%A8%BC%E5%83%8D%E7%8E%87%3Cbr%2F%3E%E2%89%92%2099.5%25%20%E3%81%AB%E5%88%B6%E7%B4%84%5D%3A%3A%3AredNode%0A%20%20%20%20%20%20D_Text%5B%22%E5%86%97%E9%95%B7%E5%8C%96%E3%81%97%E3%81%A6%E3%82%82%3Cbr%2F%3E%E3%81%93%E3%81%93%E3%81%AB%E5%BC%95%E3%81%A3%E5%BC%B5%E3%82%89%E3%82%8C%E3%82%8B%22%5D%3A%3A%3AtextOnly%0A%20%20%20%20%20%20D_Split%20--%3E%20D_B1%0A%20%20%20%20%20%20D_Split%20--%3E%20D_B2%0A%20%20%20%20%20%20D_B1%20--%3E%20D_Storage%0A%20%20%20%20%20%20D_B2%20--%3E%20D_Storage%0A%20%20%20%20%20%20D_Storage%20--%3E%20D_Total%0A%20%20%20%20%20%20D_Total%20---%20D_Text%0A%20%20%20%20end%0A%0A%20%20%20%20linkStyle%203%20stroke%3Anone%3B%0A%20%20%20%20linkStyle%208%20stroke%3Anone%3B%0A%20%20%20%20linkStyle%2014%20stroke%3Anone%3B%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[g(" Loading... ",-1)])]),_:1}))]),t[6]||(t[6]=d('<p>オンプレとクラウドでは、同じ「稼働率」でも数字の意味が違う点に注意する。</p><ul><li><strong>オンプレ</strong><br> 製品の公表値は、部品の故障率予測・冗長設計・実績補正から導いた設計値であり、「製品そのものの稼働率」と理解して実務上問題ない。ただし IA サーバーのように構成の組み合わせが多いものは非公開で計算も難しく、実際には仮想化基盤全体の稼働率で考えることになる。</li><li><strong>クラウド</strong><br> 公開値は、設計値というよりベンダーの財務上の防衛ライン（商用上の下限）に近い。実際の設計値はより高いはずだが開示されないため、鵜呑みにはせず「最悪でもこの水準」とみなす。その数字だと毎月どのくらい停止するかをタイムラインで描き、業務の期待に足りるかを確かめる。運用が始まったら、自分たちの実績値で見直していく。</li></ul><p>また、障害は機器（ハコ）の故障だけではない。アクセス高騰を発端とするミドルウェアの不調や、特定条件で発生するバグなども起きる。原因の種類によって対策の型が異なるため、分けて考える。</p><table tabindex="0"><thead><tr><th style="text-align:left;">障害の種類</th><th style="text-align:left;">主な対策</th></tr></thead><tbody><tr><td style="text-align:left;">機器（ハコ・ハードウェア）の故障</td><td style="text-align:left;">公開情報から故障率を見積もり、冗長構成と機器の更改時期を計画する</td></tr><tr><td style="text-align:left;">アクセス高騰（負荷急増）によるミドルウェア不調</td><td style="text-align:left;">流量制御と、その対応をセットで設計する</td></tr><tr><td style="text-align:left;">ミドルウェアのバグ・不調（特定条件で発動するバグなど）</td><td style="text-align:left;">外形監視と、切り替えの高速化で抑える</td></tr></tbody></table><p>設計値が事業の期待（要求値）に届かない場合、とりうる手は原理的に2つである。</p><ul><li>別の耐障害機構（別リージョン・別クラウド、あるいはオンプレ併用）を持ち込むこと</li><li>業務側で吸収すること（復旧までの時間を前提に、代替運用や業務調整をあらかじめ用意する）</li></ul><p>なお、冗長機構そのものが期待どおり働かない（フェイルオーバーに失敗する）可能性も織り込んでおく。</p><div class="tip custom-block"><p class="custom-block-title">冗長構成の半死への備え</p><p>完全に停止すれば冗長構成は切り替わるが、完全には止まっていない&quot;半死&quot;の状態ではうまく切り替わらないことがある。例えば、10秒に1〜2回しか応答しない、応答は返ってくるが極端に遅い、といったケースである。単純な死活監視では切り替えや切り離しが起きない。1件ずつの遅れは停止と言うほどではなくても、積み重なると処理が追いつかなくなり、やがて業務が回らなくなる。</p><p>半死への対応は、要件と設計で受け持つ範囲を分けて考える。</p><ul><li><strong>要件</strong>: 「業務影響で稼働率を数える」という方針に留める（→「実績値」）。応答時間やエラー率の閾値といった細部までは、要件には含めない</li><li><strong>設計</strong>: 半死を検知して切り離す作り込み。浅い死活監視ではなく処理の成否まで見る深いヘルスチェックや、閾値監視、サーキットブレーカーによる切り離しなどがある</li></ul><p>どこまで作り込むかは、業務にとって許容できない劣化はどこにあるかを起点に（→ 要求値の「痛み」）、コストと相談して決める。</p></div><h4 id="実績値-運用で検証し、次に活かす" tabindex="-1">実績値（運用で検証し、次に活かす） <a class="header-anchor" href="#実績値-運用で検証し、次に活かす" aria-label="Permalink to &quot;実績値（運用で検証し、次に活かす）&quot;">​</a></h4><p>実績値は、運用のなかで実際に記録された結果である。要求値・要件・設計値と突き合わせ、乖離があれば構成や要件を見直す。あわせて、次期システムの要求水準を定めるためのベースラインとして残す（→ <a href="./overview.html#継承">Why章「継承」</a>）。</p><p>実績値を測るうえで、まず決めておきたいのが「何をもって停止とみなすか」である。基準にすべきは、部品やジョブが失敗したかではなく、利用者や業務に影響が出たかである。例えば夜間バッチが途中で失敗しても、定められたバッチウィンドウ内にリカバリでき、後続業務に影響が及ばなければ、稼働率を下げる停止とは数えない。</p><div class="tip custom-block"><p class="custom-block-title">稼働率をどう数えるか</p><p>稼働率の数字は、運用が記録した障害の「検知〜復旧」時刻を積み上げて算定するのが一般的である。その際、何をもって停止とみなすかは、次の基準がある。</p><ul><li><strong>ヘルスチェックの応答可否</strong>: 外形的に応答が返るかを見る方法。ただしこれだけだと、サービスは応答しているのに業務が回っていない状態を取りこぼす懸念がある</li><li><strong>実リクエストの成功率</strong>: 実際の処理が成功した割合から判定する。一定の閾値を下回っている時間帯を、利用不可として集計する</li></ul><p>いずれにせよ、何を停止として数えるかで数字は変わるため、測り方も要件合意の前提として揃えておく（→ 第一部 <a href="./overview.html#step10">STEP10 ステークホルダー合意</a>）。</p></div><p>なお、要求値は一度決めたら固定ではない。事業や利用のされ方が変われば求められる可用性も変わるため、見直す機会をあらかじめ決めておく。ただし「どれだけ変わったら見直すか」を精密に定義するのは難しいので、次の二本立てで構える。</p><ul><li><strong>定期の点検</strong>: 年1回や予算・計画の節目など、定点で「いまの要求水準は妥当か」を確認する</li><li><strong>変化のトリガー</strong>: 利用者数や取引量が想定を大きく超えた、事業の局面が変わった、重大障害や実績値の未達が出た、といった合図で臨時に見直す</li></ul><p>とくに利用が伸びると、停止したときに影響を受ける人・取引が増え、停止の痛み（→ 要求値）そのものも大きくなる。同じ稼働率でも、以前は許容できた停止が許容できなくなる場合もある。</p><h3 id="耐障害性" tabindex="-1">耐障害性 <a class="header-anchor" href="#耐障害性" aria-label="Permalink to &quot;耐障害性&quot;">​</a></h3><p>耐障害性は「そもそも止まりにくくする」ための設計である。ただし、その水準は設計者が独断で決めるものではなく、非機能要件として合意しておく部分がある。非機能要件は、外から見える結果（稼働率）だけでなく、内側の耐性水準やポリシーも含む。内側の話でも、次の2つの理由から要件定義中に決めておきたい。</p><ul><li><strong>受容するリスクの事業判断だから</strong>: 例えば「リージョン全損は対象外とする」は、その障害が起きたときの損失を事業が受け入れるという判断であり、黙って設計に委ねてよいものではない</li><li><strong>後続の設計を強く縛り、後戻りが高価だから</strong>: マルチ AZ とマルチリージョンのどちらにするかは、構成の土台を決める重要な意思決定であるため</li></ul><p>ただし、要件で決めるのは「どこまでの障害に耐えるか」という水準・範囲・方針までである。「どの AZ（アベイラビリティゾーン）を2つ選ぶか」「リトライ回数の上限」といった具体的な構成は設計に委ねる（→ アンチパターン「技術的な実現手段まで要件に書いてしまう」）。稼働率の目標は冗長化の必要性を示唆するが、どの障害範囲を対象とし、どのリスクを受容するかは、別立てで明示的に合意する。</p><p>次の表は、可用性まわりの項目を「外から見える結果か、内側の耐性か」で分類し、要件で決めることと設計に委ねることを整理したものである。</p><table tabindex="0"><thead><tr><th style="text-align:left;">性質</th><th style="text-align:left;">項目</th><th style="text-align:left;">要件定義で決めること</th><th style="text-align:left;">設計に委ねること</th></tr></thead><tbody><tr><td style="text-align:left;">外形の結果指標</td><td style="text-align:left;">稼働率</td><td style="text-align:left;">目標水準（99.9％ など）</td><td style="text-align:left;">到達させる構成全般</td></tr><tr><td style="text-align:left;">両方（利用者にも見え、設計も縛る）</td><td style="text-align:left;">RTO・サービス切り替え時間</td><td style="text-align:left;">許容する最大時間</td><td style="text-align:left;">フェイルオーバー方式の実装</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">RPO</td><td style="text-align:left;">許容するデータ損失</td><td style="text-align:left;">レプリケーション方式</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">フェイルオーバーの自動／手動</td><td style="text-align:left;">自動か手動かの方針（RTO・運用体制・ガバナンスから決まる）</td><td style="text-align:left;">検知の閾値・切り替え機構の実装</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">縮退運用レベル</td><td style="text-align:left;">どこまで機能を落として継続してよいか</td><td style="text-align:left;">縮退の実装</td></tr><tr><td style="text-align:left;">内側の耐性水準</td><td style="text-align:left;">障害耐性の範囲</td><td style="text-align:left;">どこまでの障害に耐えるか（例: 単一 AZ 障害は継続／リージョン全損は対象外）</td><td style="text-align:left;">AZ・リージョン構成の具体</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">単一障害点（SPOF）</td><td style="text-align:left;">SPOF を許容しない方針</td><td style="text-align:left;">各層の SPOF 特定と冗長化の具体</td></tr></tbody></table><p>補足として、2点を押さえておく。</p><ul><li><strong>見落としやすい SPOF</strong>: 認証基盤・DNS・共有ストレージは単一障害点になりやすく、しかも見落とされやすい。「SPOF を持たない」という方針を掲げたうえで、これらを設計で意識的に洗い出す</li><li><strong>フェイルオーバーの見極め</strong>: 切り替え中は利用者が一時的に使えず、停止時間の一部になるため、切り替え時間は設計任せにせず要件で押さえる。自動か手動かは、RTO が厳しいほど自動に寄る。手動だと、検知・判断・操作に人手が入って RTO を圧迫するためである。誤切り替えを避けて承認を挟むかは、運用・ガバナンスの判断で決まる</li></ul><h4 id="依存先が止まったときの振る舞い-縮退運転の是非" tabindex="-1">依存先が止まったときの振る舞い（縮退運転の是非） <a class="header-anchor" href="#依存先が止まったときの振る舞い-縮退運転の是非" aria-label="Permalink to &quot;依存先が止まったときの振る舞い（縮退運転の是非）&quot;">​</a></h4><p>外部 API・DB・認証基盤などの依存先が止まったとき、システムをどう振る舞わせるかは、要件で明示的に決める。大きく2つの選択肢がある。</p><ul><li><strong>止める</strong>: 依存先が使えないと判断したら、機能全体を停止する。挙動が「動く・止まる」に絞られ、テストや運用も単純になる</li><li><strong>縮退して続ける</strong>: 一部だけ生かす（例: 更新は止めるが参照は継続する）。利用者への影響は小さくできるが、正常・縮退・復帰と状態が増え、その組み合わせをテストする必要がある。中途半端な継続は、古いデータの参照や、片系だけ更新された不整合を招きやすい</li></ul><p>明確な理由がなければ、止める側に倒すほうが安全である。縮退を選ぶなら、「どの機能を・どんな条件で落とし・どう戻すか」を正規の設計・テスト対象として扱い、&quot;とりあえず参照だけ生かす&quot;といった成り行きの縮退にはしない。</p><h3 id="災害対策と事業継続" tabindex="-1">災害対策と事業継続 <a class="header-anchor" href="#災害対策と事業継続" aria-label="Permalink to &quot;災害対策と事業継続&quot;">​</a></h3><p>拠点やリージョンの全体が使えなくなるような広域障害に備えるのが、災害対策（DR: Disaster Recovery・BCP: Business Continuity Plan）である。日々の障害と違い、システム単独では完結せず、事業をどう続けるか（BCP）と一体で考える。データが失われないための備え（→<a href="#バックアップとデータ保全">バックアップとデータ保全</a>）は前提とする。そのうえで、ここでは「どれだけ速く・どこまで業務を再開するか」と「どこへ逃がすか」を決める。</p><h4 id="復旧レベルを選ぶ" tabindex="-1">復旧レベルを選ぶ <a class="header-anchor" href="#復旧レベルを選ぶ" aria-label="Permalink to &quot;復旧レベルを選ぶ&quot;">​</a></h4><p>広域障害からどう復旧するかは、大きく4つのレベルに分かれる（AWS の災害対策戦略の分類が広く使われている）。どれを選ぶかは、許容できる復旧の遅さ（RTO）と失ってよいデータ量（RPO）で決まる。速く戻せる方式ほど、待機環境を厚く持つぶんコストは跳ね上がる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">概要</th><th style="text-align:left;">RTO／RPO の目安</th><th style="text-align:left;">コスト</th></tr></thead><tbody><tr><td style="text-align:left;">バックアップ＆リストア</td><td style="text-align:left;">待機環境は持たず、被災後にバックアップから環境を作って復旧する</td><td style="text-align:left;">RTO・RPO とも数時間〜</td><td style="text-align:left;">低</td></tr><tr><td style="text-align:left;">パイロットライト</td><td style="text-align:left;">データは常時複製し、DB など中核だけ用意しておく。アプリ層は止めておき、被災時に起動・拡張する</td><td style="text-align:left;">RTO 数十分／RPO 数分</td><td style="text-align:left;">低〜中</td></tr><tr><td style="text-align:left;">ウォームスタンバイ</td><td style="text-align:left;">縮小版だが動く待機環境を常時稼働させ、被災時に本番規模へ拡張する</td><td style="text-align:left;">RTO 数分／RPO 数秒〜数分</td><td style="text-align:left;">中〜高</td></tr><tr><td style="text-align:left;">マルチサイト（アクティブ/アクティブ）</td><td style="text-align:left;">複数リージョンで本番を常時稼働させ、同時に処理する</td><td style="text-align:left;">RTO・RPO ほぼゼロ</td><td style="text-align:left;">高</td></tr></tbody></table><p>最も軽いバックアップ＆リストアは、<a href="#バックアップとデータ保全">バックアップとデータ保全</a>で述べた備えを、被災時の復旧手段としてそのまま使うレベルである。より速い復旧が要るほど、パイロットライト・ウォームスタンバイ・マルチサイトへと待機環境を厚くしていく。</p><div class="info custom-block"><p class="custom-block-title">参考</p><p><a href="https://aws.amazon.com/jp/blogs/news/disaster-recovery-strategy-in-the-cloud/" target="_blank" rel="noreferrer">AWS「クラウドにおける災害対策の戦略」</a></p></div><h4 id="待機サイトをどこに置くか" tabindex="-1">待機サイトをどこに置くか <a class="header-anchor" href="#待機サイトをどこに置くか" aria-label="Permalink to &quot;待機サイトをどこに置くか&quot;">​</a></h4><p>どこへ逃がすか、つまり待機サイトをどのリージョンに置くかも、災害対策の要件として決めておく。大阪にするかシンガポールにするか、といった選択は、次の観点で判断する。</p><ul><li><strong>同時被災を避ける距離</strong>: 本番と待機サイトが近すぎると、同じ地震や広域停電で共倒れになる。十分に離れたリージョンを選ぶ。ただし離すほど、後述のレイテンシとコストは増える</li><li><strong>データ主権・法規制</strong>: 国外のリージョンにデータを置いてよいかは、可用性ではなく制約・規制の判断である。個人情報の保護やデータの国外持ち出しに関する規制で、置ける場所が縛られることもある（→ 第一部 <a href="./overview.html#step3">STEP3 制約の洗い出し</a>）。扱うデータによっては、準拠法が国内法か、国内所管の裁判所で係争できるかを契約時に確認する</li><li><strong>レイテンシとコスト</strong>: 遠いリージョンほど、平常時のデータ複製の遅延や、データ転送費・二重運用のコストが増える</li></ul><p>とくに国内か国外かは、距離やコストより先に、データ主権の制約で選択肢が絞られやすい。技術的な最適地を探る前に、そもそもデータを置いてよい場所はどこかを確かめる。</p><h4 id="事業継続-bcp-と揃える" tabindex="-1">事業継続（BCP）と揃える <a class="header-anchor" href="#事業継続-bcp-と揃える" aria-label="Permalink to &quot;事業継続（BCP）と揃える&quot;">​</a></h4><p>災害対策は、システムを復旧させれば終わりではない。止まった業務をどの順で立て直し、その間どう事業を続けるかという事業継続（BCP）と揃えて、初めて意味を持つ。要件としては、次の2つを押さえる。</p><ul><li><strong>復旧業務の優先順位</strong>: 被災時にすべてを同時には戻せない。どの業務から復旧させるか（例えば Critical → High → Medium）を事業の重要度で順位づけ、システムの復旧順序もこれに従わせる</li><li><strong>業務・拠点・人の継続体制</strong>: システムが復旧しても、業務を回す拠点・人員・手順が動かなければ事業は再開できない。代替拠点、要員、業務プロセスの継続まで含めて備える</li></ul><div class="tip custom-block"><p class="custom-block-title">落とし穴: システムだけ突出させない</p><p>マルチリージョンのような高価な冗長は、業務・組織・拠点の BCP（代替拠点）と整合していなければならない。システムだけレベルを上げても ROI が出ず、実運用でも機能しないためである。高可用オプションは、業務側の継続体制とセットで初めて意味を持つ（→ 第一部 <a href="./overview.html#全体最適">Where「全体最適」</a>／<a href="./overview.html#心得">心得「過剰品質を避ける」</a>）。</p></div><p>なお、災害をどう検知して DR をいつ発動するか・本番が復旧したあとどう切り戻すか・DR 訓練をどの頻度で行うか、といった点は運用要件で取り決めるとしてここでは触れない。網羅的な項目と値の例は、<a href="./appendix.html#可用性の定義項目チェックリスト">Appendix「可用性の定義項目チェックリスト」</a>の災害対策・BCP を参照。</p>',43))])}const _=o(h,[["render",E]]);export{C as __pageData,_ as default};
